<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('gallery.manage');verify_csrf();$pdo=staff_db();feature_table($pdo,'project_gallery_entries');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',fpost('title')),'-'));$pdo->prepare('INSERT INTO project_gallery_entries(project_id,title,slug,category,short_description,full_description,location_label,completion_date,cover_image,is_featured,is_published,published_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([fint('project_id'),fpost('title'),$slug,fpost('category')?:null,fpost('short_description')?:null,fpost('full_description')?:null,fpost('location_label')?:null,fpost('completion_date')?:null,fpost('cover_image')?:null,isset($_POST['is_featured'])?1:0,isset($_POST['is_published'])?1:0,isset($_POST['is_published'])?date('Y-m-d H:i:s'):null,$staff['id']]);flash('success','Gallery project added.');staff_redirect('staff/admin/gallery.php');}
$projects=project_options($pdo);$rows=db_rows($pdo,'SELECT g.*,p.project_code FROM project_gallery_entries g LEFT JOIN projects p ON p.id=g.project_id ORDER BY g.is_featured DESC,g.sort_order,g.created_at DESC');$pageTitle='Project Gallery';require __DIR__.'/../../includes/staff/header.php';module_head('Public Website','Project Gallery','Publish completed IdeaRE work to the customer-facing portfolio.');?>
<section class="staff-panel"><form method="post" class="mini-form"><?=csrf_field()?><label>Project<select name="project_id"><option value="">Standalone</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=h($p['project_code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Title<input name="title" required></label><label>Category<input name="category" placeholder="Kitchen"></label><label>Location label<input name="location_label" placeholder="Johor Bahru"></label><label>Completion date<input type="date" name="completion_date"></label><label>Cover image path<input name="cover_image" placeholder="assets/images/projects/..."></label><label>Short description<input name="short_description"></label><label><input type="checkbox" name="is_featured"> Featured</label><label><input type="checkbox" name="is_published"> Published</label><button class="btn primary">Add project</button></form></section><section class="staff-panel table-panel"><table><thead><tr><th>Title</th><th>Category</th><th>Linked project</th><th>Published</th><th>Featured</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h($r['title'])?></b></td><td><?=h($r['category']?:'—')?></td><td><?=h($r['project_code']?:'—')?></td><td><?=$r['is_published']?'Yes':'No'?></td><td><?=$r['is_featured']?'Yes':'No'?></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>